/** Lower-cased text an entry is found by. */
export const searchText = (entry) => `${entry.name} ${entry.description} ${entry.tags.join(' ')} ${entry.level}`.toLowerCase();
/** The entries that match a query, a level (or all) and every one of the chosen tags. */
export function filterCatalogue(entries, query, level, chosen) {
    const words = query.toLowerCase().split(/\s+/).filter(Boolean);
    return entries.filter((entry) => {
        if (level !== 'All' && entry.level !== level)
            return false;
        if (!chosen.every((t) => entry.tags.includes(t)))
            return false;
        const text = searchText(entry);
        return words.every((w) => text.includes(w));
    });
}
/** The import line for an entry. */
export const importLine = (entry) => `import { ${entry.name} } from '@bonbon-ui/core${entry.entry ? `/${entry.entry}` : ''}';`;
